import { useState, useEffect } from 'react';
import { useAuth } from './AuthContext';
import Login from './Login';
import Player from './components/Player';
import SongList from './components/SongList';
import SearchBar from './components/SearchBar';
import './styles/main.css';

function App() {
  const { user, logout } = useAuth();
  const [songs, setSongs] = useState([]);
  const [currentSong, setCurrentSong] = useState(null);
  const [searchTerm, setSearchTerm] = useState('eminem');
  const [recentSongs, setRecentSongs] = useState([]);
  const [playlists, setPlaylists] = useState({});
  const [newPlaylistName, setNewPlaylistName] = useState('');
  const [currentTab, setCurrentTab] = useState('results');
  const [addToPlaylistSong, setAddToPlaylistSong] = useState(null);
  const [isDarkMode, setIsDarkMode] = useState(false);

  // Search for songs
  async function searchSongs(term) {
    try {
      const response = await fetch(
        `https://deezerdevs-deezer.p.rapidapi.com/search?q=${term}`,
        {
          headers: {
            'X-RapidAPI-Key': '3319ab7c91msh6b1b05141c68417p1783ffjsn6acb6efc6170',
            'X-RapidAPI-Host': 'deezerdevs-deezer.p.rapidapi.com'
          }
        }
      );
      const data = await response.json();
      setSongs(data.data || []);
    } catch (error) {
      console.error('API error:', error);
    }
  }

  // Play a song
  function playSong(song) {
    setCurrentSong(song);
    if (!recentSongs.find(s => s.id === song.id)) {
      setRecentSongs([song, ...recentSongs.slice(0, 9)]);
    }
  }

  // Add song to playlist
  function addToPlaylist(playlistName, song) {
    setPlaylists(prev => {
      const updated = { ...prev };
      if (!updated[playlistName]) updated[playlistName] = [];
      if (!updated[playlistName].find(s => s.id === song.id)) {
        updated[playlistName].push(song);
      }
      return updated;
    });
    setAddToPlaylistSong(null);
  }

  // Remove song from playlist
  function removeSong(playlistName, songId) {
    setPlaylists(prev => {
      const updated = { ...prev };
      updated[playlistName] = updated[playlistName].filter(s => s.id !== songId);
      return updated;
    });
  }

  // Create a new playlist
  function createPlaylist() {
    if (newPlaylistName.trim() && !playlists[newPlaylistName]) {
      setPlaylists({ ...playlists, [newPlaylistName]: [] });
      setNewPlaylistName('');
    }
  }

  // Initial search
  useEffect(() => {
    if (user) searchSongs(searchTerm);
  }, [user, searchTerm]);

  // If user not logged in, show login page
  if (!user) return <Login />;

  return (
    <div className={`app ${isDarkMode ? 'dark' : ''}`}>
      <header>
        <img src="https://upload.wikimedia.org/wikipedia/commons/1/11/CSUF_Titans_Logo.svg" alt="CSUF Logo" />
        <h1>Tuffy Music</h1>
        <div className="user-controls">
          <button onClick={() => setIsDarkMode(!isDarkMode)}>
            {isDarkMode ? 'Light' : 'Dark'}
          </button>
          <button onClick={logout}>Logout</button>
          <span>{user.email}</span>
        </div>
      </header>

      {/* Only show search on results tab */}
      {currentTab === 'results' && (
        <SearchBar onSearch={(term) => {
          setSearchTerm(term);
          setCurrentTab('results');
          searchSongs(term);
        }} />
      )}

      <div className="tabs">
        <button 
          className={currentTab === 'results' ? 'active' : ''}
          onClick={() => setCurrentTab('results')}
        >
          Results
        </button>
        <button 
          className={currentTab === 'playlists' ? 'active' : ''}
          onClick={() => setCurrentTab('playlists')}
        >
          Playlists
        </button>
        <button 
          className={currentTab === 'recent' ? 'active' : ''}
          onClick={() => setCurrentTab('recent')}
        >
          Recent
        </button>
      </div>

      {currentTab === 'results' && (
        <>
          <h2>Results</h2>
          <SongList 
            songs={songs} 
            onPlay={playSong}
            onAddToPlaylist={setAddToPlaylistSong} 
          />
        </>
      )}

      {currentTab === 'playlists' && (
        <>
          <h2>Your Playlists</h2>
          <div className="create-playlist">
            <input
              value={newPlaylistName}
              onChange={(e) => setNewPlaylistName(e.target.value)}
              placeholder="New Playlist Name"
            />
            <button onClick={createPlaylist}>Create</button>
          </div>
          <div className="playlists">
            {Object.keys(playlists).map(name => (
              <div key={name} className="playlist-card">
                <h3>{name}</h3>
                {playlists[name].length === 0 ? (
                  <p>No songs yet</p>
                ) : (
                  playlists[name].map(song => (
                    <div key={song.id} className="playlist-song">
                      <img 
                        src={song.album.cover_small} 
                        alt={song.title}
                        onClick={() => playSong(song)}
                      />
                      <div>
                        <p>{song.title}</p>
                        <p className="small">{song.artist.name}</p>
                      </div>
                      <button 
                        className="remove-btn" 
                        onClick={() => removeSong(name, song.id)}
                      >
                        🗑️
                      </button>
                    </div>
                  ))
                )}
              </div>
            ))}
          </div>
        </>
      )}

      {currentTab === 'recent' && (
        <>
          <h2>Recent Plays</h2>
          <SongList 
            songs={recentSongs} 
            onPlay={playSong}
            onAddToPlaylist={setAddToPlaylistSong} 
          />
        </>
      )}

      {currentSong && (
        <Player 
          song={currentSong} 
          onClose={() => setCurrentSong(null)} 
        />
      )}

      {addToPlaylistSong && (
        <div className="modal">
          <div className="modal-content">
            <h3>Add to Playlist</h3>
            {Object.keys(playlists).length === 0 ? (
              <p>No playlists yet</p>
            ) : (
              <ul>
                {Object.keys(playlists).map(name => (
                  <li 
                    key={name} 
                    onClick={() => addToPlaylist(name, addToPlaylistSong)}
                  >
                    {name}
                  </li>
                ))}
              </ul>
            )}
            <button onClick={() => setAddToPlaylistSong(null)}>Cancel</button>
          </div>
        </div>
      )}
    </div>
  );
}

export default App;
